```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.span_name, (s.span_id IS NULL) unmatched, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) p50, round(min(c.duration)/1e6,1) mn, round(max(c.duration)/1e6,1) mx FROM abnormal_traces c LEFT JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.span_name='geo.Geo/Nearby' GROUP BY 1,2",
          "claim": "All search→geo.Geo/Nearby client spans take 1.4–3.0 s (p50 about 1.6 s), versus about 0.6 ms in normal traffic."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(approx_quantile(c.duration,0.95)/1e6,1) c_p95_ms, round(approx_quantile(s.duration,0.95)/1e6,2) s_p95_ms, round(min(c.duration - s.duration)/1e6,1) min_gap_ms, round(max(c.duration - s.duration)/1e6,1) max_gap_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.span_name='geo.Geo/Nearby' GROUP BY 1,2",
          "claim": "Matched geo server spans run in about 0.2 ms, so 1.5–2.8 s of the search→geo client time is spent before geo's handler starts."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='search' AND span_name IN ('rate.Rate/GetRates','geo.Geo/Nearby') AND attr_span_kind='Client' GROUP BY 1",
          "claim": "Search's outgoing call to rate stays at about 8 ms p95 while its call to geo is about 2.6 s, so only one outgoing path is slowed."
        }
      ]
    },
    {
      "service": "profile",
      "fault_kind": "container_memory_saturated",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT date_trunc('minute', time) t, round(avg(value)/1e6,1) rss_mb FROM abnormal_metrics WHERE service_name='profile' AND metric='container.memory.rss' GROUP BY 1 ORDER BY 1",
          "claim": "Profile container RSS rises from about 13 MB in normal traffic to about 797 MB and plateaus during the incident."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(approx_quantile(duration,0.95)/1e6,2) p95_ms FROM abnormal_traces WHERE service_name='profile' GROUP BY 1,2,3",
          "claim": "Profile's own server and memcached spans have p95 about 1.3 ms and 1.0 ms during the incident, up from about 0.8 ms and 0.6 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, round(approx_quantile(duration,0.95)/1e6,2) p95_ms, count(*) n FROM abnormal_traces WHERE span_name='profile.Profile/GetProfiles' AND attr_span_kind='Client' GROUP BY 1,2",
          "claim": "Frontend's client-side GetProfiles p95 rises slightly, from about 1.7 ms to 1.9 ms, when calling profile."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE (service_name='frontend' AND span_name='search.Search/Nearby' AND attr_span_kind='Client') OR (service_name='search' AND span_name='search.Search/Nearby' AND attr_span_kind='Server') OR (service_name='frontend' AND span_name='HTTP /hotels') GROUP BY 1,2,3",
          "claim": "Search's slow Nearby server time (about 2.6 s p95) appears in frontend's Nearby client spans and in its /hotels HTTP responses."
        }
      ]
    },
    {
      "from": "profile",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, round(approx_quantile(duration,0.95)/1e6,2) p95_ms FROM abnormal_traces WHERE span_name='profile.Profile/GetProfiles' GROUP BY 1,2,3",
          "claim": "Profile's GetProfiles server p95 rises from about 0.8 ms to 1.3 ms, and frontend's client-side GetProfiles p95 rises slightly."
        }
      ]
    }
  ]
}
```

